import React, { useState, useEffect } from 'react';
import { useSearchParams, useParams } from 'react-router-dom';
import { getProducts, getProductCategories, getProductById } from '../services/api';
import ProductCard from '../components/ProductCard';
import { useTheme } from '../context/ThemeContext';
import Toast from '../components/Toast';
import useToast from '../hooks/useToast';

const Products = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const { id } = useParams();
  const [products, setProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);
  const [singleProduct, setSingleProduct] = useState(null);
  const [pagination, setPagination] = useState({
    page: 1,
    pages: 1,
    total: 0
  });
  const { isDarkMode } = useTheme();
  const { toasts, removeToast } = useToast();

  const category = searchParams.get('category') || '';
  const search = searchParams.get('search') || '';
  const page = Number(searchParams.get('page')) || 1;
  const sort = searchParams.get('sort') || 'newest';
  const minPrice = searchParams.get('minPrice') || '';
  const maxPrice = searchParams.get('maxPrice') || '';
  const minRating = searchParams.get('minRating') || '';
  const limit = Number(searchParams.get('limit')) || 24;

  useEffect(() => {
    if (id) {
      // Fetch individual product when ID is present
      fetchSingleProduct();
    } else {
      // Fetch products list when no ID
      fetchProducts();
    }
  }, [id, category, search, page, sort, minPrice, maxPrice, minRating, limit]);

  useEffect(() => {
    fetchCategories();
  }, []);

  const fetchSingleProduct = async () => {
    try {
      setLoading(true);
      const res = await getProductById(id);
      setSingleProduct(res.data);
    } catch (error) {
      console.error('Error fetching product:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchProducts = async () => {
    try {
      setLoading(true);
      const res = await getProducts({
        category,
        search,
        page,
        sort,
        minPrice: minPrice || undefined,
        maxPrice: maxPrice || undefined,
        minRating: minRating || undefined,
        limit
      });
      setProducts(res.data.products);
      setPagination({
        page: res.data.page,
        pages: res.data.pages,
        total: res.data.total
      });
    } catch (error) {
      console.error('Error fetching products:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchCategories = async () => {
    try {
      const res = await getProductCategories();
      setCategories(res.data);
    } catch (error) {
      console.error('Error fetching categories:', error);
    }
  };

  const handleCategoryChange = (cat) => {
    const params = new URLSearchParams(searchParams);
    if (cat) {
      params.set('category', cat);
    } else {
      params.delete('category');
    }
    params.delete('page');
    setSearchParams(params);
  };

  const handleSearch = (e) => {
    e.preventDefault();
    const params = new URLSearchParams(searchParams);
    const searchValue = e.target.elements.search.value.trim();
    if (searchValue) {
      params.set('search', searchValue);
    } else {
      params.delete('search');
    }
    params.delete('page');
    setSearchParams(params);
  };

  const handlePageChange = (newPage) => {
    const params = new URLSearchParams(searchParams);
    params.set('page', newPage);
    setSearchParams(params);
  };

  const setParam = (key, value) => {
    const params = new URLSearchParams(searchParams);
    if (value === '' || value === null || value === undefined) params.delete(key);
    else params.set(key, String(value));
    params.delete('page');
    setSearchParams(params);
  };

  const clearFilters = () => {
    const params = new URLSearchParams(searchParams);
    ['minPrice', 'maxPrice', 'minRating', 'sort', 'limit'].forEach((k) => params.delete(k));
    params.delete('page');
    setSearchParams(params);
  };

  const updateCart = () => {
    fetchProducts();
  };

  const getCategoryEmoji = (category) => {
    const emojis = {
      milk: '🥛',
      ghee: '🍯',
      cheese: '🧀',
      butter: '🧈',
      curd: '🥣',
      paneer: '🧊',
      cream: '🍦',
      yogurt: '🍶',
      lassi: '🥤',
      buttermilk: '🫙',
      sweets: '🍬',
      cake: '🍰'
    };
    return emojis[category] || '🥛';
  };

  return (
    <div className="fade-in min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 dark:from-black dark:to-black">
      <div className="max-w-7xl mx-auto px-4 py-8">
        {/* Modern Header */}
        <div className="text-center mb-12">
          <div className="inline-block relative group">
            <h1 className={`text-4xl md:text-5xl font-bold mb-4 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
              <span className="bg-gradient-to-r from-primary-600 via-secondary-600 to-primary-600 bg-clip-text text-transparent">
                {category ? category.charAt(0).toUpperCase() + category.slice(1) : 'All Products'}
              </span>
              {search && (
                <span className="block text-lg mt-2 text-gray-600 dark:text-gray-400">
                  Search results for "{search}"
                </span>
              )}
            </h1>
            {/* Animated Underline - Like Featured Products */}
            <div className="absolute bottom-0 left-0 w-full h-1 bg-gradient-to-r from-primary-500 to-secondary-500 rounded-full transform scale-x-0 group-hover:scale-x-100 transition-transform duration-500"></div>
          </div>
          <p className={`text-lg ${isDarkMode ? 'text-gray-300' : 'text-gray-600'} mb-4`}>
            Discover our premium dairy products
          </p>
          <div className={`inline-flex items-center px-4 py-2 rounded-full ${isDarkMode ? 'bg-gray-800 text-gray-300' : 'bg-white text-gray-600'} shadow-lg`}>
            <svg className="w-5 h-5 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 13V6a2 2 0 00-2-2H6a2 2 0 00-2 2v7m16 0v5a2 2 0 01-2 2H6a2 2 0 01-2-2v-5m16 0h-2.586a1 1 0 00-.707.293l-2.414 2.414a1 1 0 01-.707.293h-3.172a1 1 0 01-.707-.293l-2.414-2.414A1 1 0 006.586 13H4" />
            </svg>
            {pagination.total} Products Available
          </div>
        </div>

        {/* Search (top) */}
        <div className={`mb-6 p-5 rounded-3xl ${isDarkMode ? 'bg-gray-800/40 backdrop-blur-xl border border-white/10' : 'bg-white/70 backdrop-blur-xl border border-gray-200'} shadow-xl`}>
          <form onSubmit={handleSearch} className="flex flex-col md:flex-row gap-3 md:items-center">
            <div className="relative flex-1">
              <input
                type="text"
                name="search"
                placeholder="Search for dairy products..."
                defaultValue={search}
                className={`w-full px-4 py-3 pl-11 rounded-2xl border ${isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white placeholder-gray-400' : 'bg-gray-50 border-gray-300 text-gray-900 placeholder-gray-500'} focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-200`}
              />
              <svg className="absolute left-4 top-3.5 w-5 h-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
            </div>
            <div className="flex gap-3">
              <button
                type="submit"
                className="px-5 py-3 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-2xl font-medium hover:shadow-lg hover:shadow-primary-500/30 transform hover:scale-[1.02] transition-all duration-200"
              >
                Search
              </button>
              <button
                type="button"
                onClick={clearFilters}
                className={`px-5 py-3 rounded-2xl font-medium border transition-all duration-200 ${
                  isDarkMode ? 'border-white/10 text-gray-200 hover:bg-gray-700/40' : 'border-gray-200 text-gray-700 hover:bg-gray-100'
                }`}
              >
                Clear
              </button>
            </div>
          </form>

          {/* Filters (under search) */}
          <div className="mt-4">
            <details className={`lg:hidden p-4 rounded-2xl ${isDarkMode ? 'bg-gray-900/20 border border-white/10' : 'bg-white/60 border border-gray-200'} shadow-sm`}>
              <summary className={`cursor-pointer select-none font-semibold ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                Filters
              </summary>
              <div className="mt-4">
                <div className="flex justify-end mb-3">
                  <button
                    type="button"
                    onClick={clearFilters}
                    className={`text-sm font-medium px-3 py-1.5 rounded-xl border ${
                      isDarkMode ? 'border-white/10 text-gray-200 hover:bg-gray-700/40' : 'border-gray-200 text-gray-700 hover:bg-gray-100'
                    }`}
                  >
                    Clear
                  </button>
                </div>

                <div className="space-y-4">
                  <div>
                    <label className={`block text-sm font-medium mb-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                      Sort
                    </label>
                    <select
                      value={sort}
                      onChange={(e) => setParam('sort', e.target.value)}
                      className={`w-full px-4 py-3 rounded-2xl border ${isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white' : 'bg-gray-50 border-gray-300 text-gray-900'} focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-200`}
                    >
                      <option value="newest">Newest</option>
                      <option value="price_asc">Price: Low → High</option>
                      <option value="price_desc">Price: High → Low</option>
                      <option value="rating_desc">Top Rated</option>
                    </select>
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className={`block text-sm font-medium mb-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                        Min ₹
                      </label>
                      <input
                        type="number"
                        inputMode="numeric"
                        value={minPrice}
                        onChange={(e) => setParam('minPrice', e.target.value)}
                        className={`w-full px-4 py-3 rounded-2xl border ${isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white' : 'bg-gray-50 border-gray-300 text-gray-900'} focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-200`}
                        placeholder="0"
                        min="0"
                      />
                    </div>
                    <div>
                      <label className={`block text-sm font-medium mb-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                        Max ₹
                      </label>
                      <input
                        type="number"
                        inputMode="numeric"
                        value={maxPrice}
                        onChange={(e) => setParam('maxPrice', e.target.value)}
                        className={`w-full px-4 py-3 rounded-2xl border ${isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white' : 'bg-gray-50 border-gray-300 text-gray-900'} focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-200`}
                        placeholder="9999"
                        min="0"
                      />
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className={`block text-sm font-medium mb-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                        Min Rating
                      </label>
                      <select
                        value={minRating}
                        onChange={(e) => setParam('minRating', e.target.value)}
                        className={`w-full px-4 py-3 rounded-2xl border ${isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white' : 'bg-gray-50 border-gray-300 text-gray-900'} focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-200`}
                      >
                        <option value="">Any</option>
                        <option value="4">4★ & up</option>
                        <option value="3">3★ & up</option>
                        <option value="2">2★ & up</option>
                        <option value="1">1★ & up</option>
                      </select>
                    </div>
                    <div>
                      <label className={`block text-sm font-medium mb-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                        Per Page
                      </label>
                      <select
                        value={limit}
                        onChange={(e) => setParam('limit', e.target.value)}
                        className={`w-full px-4 py-3 rounded-2xl border ${isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white' : 'bg-gray-50 border-gray-300 text-gray-900'} focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-200`}
                      >
                        <option value="12">12</option>
                        <option value="24">24</option>
                        <option value="36">36</option>
                        <option value="48">48</option>
                      </select>
                    </div>
                  </div>
                </div>
              </div>
            </details>

            <div className={`hidden lg:block p-4 rounded-2xl ${isDarkMode ? 'bg-gray-900/20 border border-white/10' : 'bg-white/60 border border-gray-200'} shadow-sm`}>
              <div className="flex items-center justify-between gap-4 mb-4">
                <div className={`font-semibold ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>Filters</div>
                <button
                  type="button"
                  onClick={clearFilters}
                  className={`text-sm font-medium px-3 py-1.5 rounded-xl border ${
                    isDarkMode ? 'border-white/10 text-gray-200 hover:bg-gray-700/40' : 'border-gray-200 text-gray-700 hover:bg-gray-100'
                  }`}
                >
                  Clear
                </button>
              </div>

              <div className="grid grid-cols-12 gap-3">
                <div className="col-span-4">
                  <label className={`block text-xs font-medium mb-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                    Sort
                  </label>
                  <select
                    value={sort}
                    onChange={(e) => setParam('sort', e.target.value)}
                    className={`w-full px-4 py-3 rounded-2xl border ${isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white' : 'bg-gray-50 border-gray-300 text-gray-900'} focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-200`}
                  >
                    <option value="newest">Newest</option>
                    <option value="price_asc">Price: Low → High</option>
                    <option value="price_desc">Price: High → Low</option>
                    <option value="rating_desc">Top Rated</option>
                  </select>
                </div>

                <div className="col-span-2">
                  <label className={`block text-xs font-medium mb-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                    Min ₹
                  </label>
                  <input
                    type="number"
                    inputMode="numeric"
                    value={minPrice}
                    onChange={(e) => setParam('minPrice', e.target.value)}
                    className={`w-full px-4 py-3 rounded-2xl border ${isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white' : 'bg-gray-50 border-gray-300 text-gray-900'} focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-200`}
                    placeholder="0"
                    min="0"
                  />
                </div>

                <div className="col-span-2">
                  <label className={`block text-xs font-medium mb-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                    Max ₹
                  </label>
                  <input
                    type="number"
                    inputMode="numeric"
                    value={maxPrice}
                    onChange={(e) => setParam('maxPrice', e.target.value)}
                    className={`w-full px-4 py-3 rounded-2xl border ${isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white' : 'bg-gray-50 border-gray-300 text-gray-900'} focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-200`}
                    placeholder="9999"
                    min="0"
                  />
                </div>

                <div className="col-span-2">
                  <label className={`block text-xs font-medium mb-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                    Min Rating
                  </label>
                  <select
                    value={minRating}
                    onChange={(e) => setParam('minRating', e.target.value)}
                    className={`w-full px-4 py-3 rounded-2xl border ${isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white' : 'bg-gray-50 border-gray-300 text-gray-900'} focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-200`}
                  >
                    <option value="">Any</option>
                    <option value="4">4★ & up</option>
                    <option value="3">3★ & up</option>
                    <option value="2">2★ & up</option>
                    <option value="1">1★ & up</option>
                  </select>
                </div>

                <div className="col-span-2">
                  <label className={`block text-xs font-medium mb-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                    Per Page
                  </label>
                  <select
                    value={limit}
                    onChange={(e) => setParam('limit', e.target.value)}
                    className={`w-full px-4 py-3 rounded-2xl border ${isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white' : 'bg-gray-50 border-gray-300 text-gray-900'} focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-200`}
                  >
                    <option value="12">12</option>
                    <option value="24">24</option>
                    <option value="36">36</option>
                    <option value="48">48</option>
                  </select>
                </div>
              </div>
            </div>
          </div>

          {/* Categories (mobile chips) */}
          <div className="lg:hidden mt-4 flex items-center gap-2 overflow-x-auto scrollbar-hide pb-1">
            <button
              onClick={() => handleCategoryChange('')}
              className={`flex-shrink-0 px-4 py-2 rounded-2xl font-medium transition-all duration-200 ${
                !category
                  ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white shadow-lg'
                  : `${isDarkMode ? 'bg-gray-700/40 text-gray-200 hover:bg-gray-700/60' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'}`
              }`}
            >
              All
            </button>
            {categories.map((cat) => (
              <button
                key={cat}
                onClick={() => handleCategoryChange(cat)}
                className={`flex-shrink-0 px-4 py-2 rounded-2xl font-medium capitalize transition-all duration-200 ${
                  category === cat
                    ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white shadow-lg'
                    : `${isDarkMode ? 'bg-gray-700/40 text-gray-200 hover:bg-gray-700/60' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'}`
                }`}
              >
                {getCategoryEmoji(cat)} {cat}
              </button>
            ))}
          </div>
        </div>

        <div className="flex flex-col-reverse lg:flex-row gap-8">
          {/* Modern Sidebar - Sticky Sections with Scrollable Categories */}
          <aside className="w-full lg:w-80 flex-shrink-0 lg:sticky lg:top-8 lg:self-start flex flex-col gap-6">
            {/* Search Section - Sticky */}
            <div className={`hidden relative p-6 rounded-3xl ${isDarkMode ? 'bg-gray-800/50 backdrop-blur-xl border border-white/10' : 'bg-white/70 backdrop-blur-xl border border-gray-200'} shadow-xl flex-shrink-0`}>
              <h3 className={`text-lg font-semibold mb-4 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                🔍 Search Products
              </h3>
              <form onSubmit={handleSearch}>
                <div className="relative">
                  <input
                    type="text"
                    name="search"
                    placeholder="Search for dairy products..."
                    defaultValue={search}
                    className={`w-full px-4 py-3 pl-12 rounded-xl border ${isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white placeholder-gray-400' : 'bg-gray-50 border-gray-300 text-gray-900 placeholder-gray-500'} focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-200`}
                  />
                  <svg className="absolute left-4 top-3.5 w-5 h-5 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                  </svg>
                </div>
                <button
                  type="submit"
                  className="w-full mt-3 px-4 py-3 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-xl font-medium hover:shadow-lg hover:shadow-primary-500/30 transform hover:scale-[1.02] transition-all duration-200"
                >
                  Search
                </button>
              </form>
            </div>

            {/* Filters Section */}
            <div className={`hidden relative p-6 rounded-3xl order-2 ${isDarkMode ? 'bg-gray-800/50 backdrop-blur-xl border border-white/10' : 'bg-white/70 backdrop-blur-xl border border-gray-200'} shadow-xl flex-shrink-0`}>
              <div className="flex items-center justify-between mb-4">
                <h3 className={`text-lg font-semibold ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                  🧰 Filters
                </h3>
                <button
                  type="button"
                  onClick={clearFilters}
                  className={`text-sm font-medium px-3 py-1.5 rounded-xl border ${
                    isDarkMode ? 'border-white/10 text-gray-200 hover:bg-gray-700/40' : 'border-gray-200 text-gray-700 hover:bg-gray-100'
                  }`}
                >
                  Clear
                </button>
              </div>

              <div className="space-y-4">
                <div>
                  <label className={`block text-sm font-medium mb-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                    Sort
                  </label>
                  <select
                    value={sort}
                    onChange={(e) => setParam('sort', e.target.value)}
                    className={`w-full px-4 py-3 rounded-xl border ${isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white' : 'bg-gray-50 border-gray-300 text-gray-900'} focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-200`}
                  >
                    <option value="newest">Newest</option>
                    <option value="price_asc">Price: Low → High</option>
                    <option value="price_desc">Price: High → Low</option>
                    <option value="rating_desc">Top Rated</option>
                  </select>
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className={`block text-sm font-medium mb-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                      Min ₹
                    </label>
                    <input
                      type="number"
                      inputMode="numeric"
                      value={minPrice}
                      onChange={(e) => setParam('minPrice', e.target.value)}
                      className={`w-full px-4 py-3 rounded-xl border ${isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white' : 'bg-gray-50 border-gray-300 text-gray-900'} focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-200`}
                      placeholder="0"
                      min="0"
                    />
                  </div>
                  <div>
                    <label className={`block text-sm font-medium mb-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                      Max ₹
                    </label>
                    <input
                      type="number"
                      inputMode="numeric"
                      value={maxPrice}
                      onChange={(e) => setParam('maxPrice', e.target.value)}
                      className={`w-full px-4 py-3 rounded-xl border ${isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white' : 'bg-gray-50 border-gray-300 text-gray-900'} focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-200`}
                      placeholder="9999"
                      min="0"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className={`block text-sm font-medium mb-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                      Min Rating
                    </label>
                    <select
                      value={minRating}
                      onChange={(e) => setParam('minRating', e.target.value)}
                      className={`w-full px-4 py-3 rounded-xl border ${isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white' : 'bg-gray-50 border-gray-300 text-gray-900'} focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-200`}
                    >
                      <option value="">Any</option>
                      <option value="4">4★ & up</option>
                      <option value="3">3★ & up</option>
                      <option value="2">2★ & up</option>
                      <option value="1">1★ & up</option>
                    </select>
                  </div>
                  <div>
                    <label className={`block text-sm font-medium mb-2 ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
                      Per Page
                    </label>
                    <select
                      value={limit}
                      onChange={(e) => setParam('limit', e.target.value)}
                      className={`w-full px-4 py-3 rounded-xl border ${isDarkMode ? 'bg-gray-700/50 border-gray-600 text-white' : 'bg-gray-50 border-gray-300 text-gray-900'} focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent transition-all duration-200`}
                    >
                      <option value="12">12</option>
                      <option value="24">24</option>
                      <option value="36">36</option>
                      <option value="48">48</option>
                    </select>
                  </div>
                </div>
              </div>
            </div>

            {/* Categories Section - Sticky with Scrollable List */}
            <div className={`hidden lg:flex flex-1 relative p-6 rounded-3xl order-1 ${isDarkMode ? 'bg-gray-800/50 backdrop-blur-xl border border-white/10' : 'bg-white/70 backdrop-blur-xl border border-gray-200'} shadow-xl overflow-hidden flex flex-col min-h-0`}>
              <h3 className={`text-lg font-semibold mb-4 flex-shrink-0 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                📦 Categories
              </h3>
              <ul className="space-y-2 overflow-y-auto scrollbar-hide max-h-[45vh] pr-1">
                <li>
                  <button
                    onClick={() => handleCategoryChange('')}
                    className={`w-full text-left px-4 py-3 rounded-xl transition-all duration-200 font-medium ${
                      !category 
                        ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white shadow-lg transform scale-[1.02]' 
                        : `${isDarkMode ? 'text-gray-300 hover:bg-gray-700/50' : 'text-gray-700 hover:bg-gray-100'}`
                    }`}
                  >
                    🥛 All Products
                  </button>
                </li>
                {categories.map((cat) => (
                  <li key={cat}>
                    <button
                      onClick={() => handleCategoryChange(cat)}
                      className={`w-full text-left px-4 py-3 rounded-xl transition-all duration-200 font-medium capitalize ${
                        category === cat 
                          ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white shadow-lg transform scale-[1.02]' 
                          : `${isDarkMode ? 'text-gray-300 hover:bg-gray-700/50' : 'text-gray-700 hover:bg-gray-100'}`
                      }`}
                    >
                      {getCategoryEmoji(cat)} {cat}
                    </button>
                  </li>
                ))}
              </ul>
            </div>
          </aside>

          {/* Products Grid */}
          <div className="flex-1 lg:pl-8 lg:pr-4 py-4">

          {loading ? (
            <div className="flex justify-center items-center py-20">
              <div className="relative">
                <div className="w-16 h-16 border-4 border-primary-200 border-t-primary-600 rounded-full animate-spin"></div>
                <div className="absolute inset-0 flex items-center justify-center">
                  <div className="w-8 h-8 bg-gradient-to-br from-primary-500 to-secondary-500 rounded-full animate-pulse"></div>
                </div>
              </div>
            </div>
          ) : id && singleProduct ? (
            // Individual Product View - Smaller Size
            <div className="max-w-2xl mx-auto p-6">
              <ProductCard 
                key={singleProduct._id} 
                product={singleProduct} 
                onCartUpdate={updateCart}
                index={0}
                isDetailView={true}
              />
            </div>
          ) : products.length > 0 ? (
            <>
              {/* Modern Products Grid - With padding for hover effects */}
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-x-6 gap-y-12 mb-8 py-6 px-2">
                {products.map((product, index) => (
                  <ProductCard 
                    key={product._id} 
                    product={product} 
                    onCartUpdate={updateCart}
                    index={index}
                  />
                ))}
              </div>

              {/* Modern Pagination */}
              {pagination.pages > 1 && (
                <div className={`flex justify-center items-center space-x-2 p-4 rounded-2xl ${isDarkMode ? 'bg-gray-800/50 backdrop-blur-xl border border-white/10' : 'bg-white/70 backdrop-blur-xl border border-gray-200'} shadow-xl`}>
                  <button
                    onClick={() => handlePageChange(pagination.page - 1)}
                    disabled={pagination.page === 1}
                    className={`px-4 py-2 rounded-xl font-medium transition-all duration-200 ${
                      pagination.page === 1
                        ? 'bg-gray-200 text-gray-400 cursor-not-allowed'
                        : 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white hover:shadow-lg hover:shadow-primary-500/30 transform hover:scale-[1.02]'
                    }`}
                  >
                    ← Previous
                  </button>
                  
                  <div className="flex items-center space-x-1">
                    {[...Array(Math.min(5, pagination.pages))].map((_, i) => {
                      let pageNum;
                      if (pagination.pages <= 5) {
                        pageNum = i + 1;
                      } else if (pagination.page <= 3) {
                        pageNum = i + 1;
                      } else if (pagination.page >= pagination.pages - 2) {
                        pageNum = pagination.pages - 4 + i;
                      } else {
                        pageNum = pagination.page - 2 + i;
                      }
                      
                      return (
                        <button
                          key={pageNum}
                          onClick={() => handlePageChange(pageNum)}
                          className={`w-10 h-10 rounded-xl font-medium transition-all duration-200 ${
                            pagination.page === pageNum
                              ? 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white shadow-lg transform scale-[1.1]'
                              : `${isDarkMode ? 'bg-gray-700 text-gray-300 hover:bg-gray-600' : 'bg-gray-100 text-gray-700 hover:bg-gray-200'}`
                          }`}
                        >
                          {pageNum}
                        </button>
                      );
                    })}
                  </div>
                  
                  <button
                    onClick={() => handlePageChange(pagination.page + 1)}
                    disabled={pagination.page === pagination.pages}
                    className={`px-4 py-2 rounded-xl font-medium transition-all duration-200 ${
                      pagination.page === pagination.pages
                        ? 'bg-gray-200 text-gray-400 cursor-not-allowed'
                        : 'bg-gradient-to-r from-primary-500 to-secondary-500 text-white hover:shadow-lg hover:shadow-primary-500/30 transform hover:scale-[1.02]'
                    }`}
                  >
                    Next →
                  </button>
                </div>
              )}
            </>
          ) : (
            <div className={`text-center py-20 rounded-3xl ${isDarkMode ? 'bg-gray-800/50 backdrop-blur-xl border border-white/10' : 'bg-white/70 backdrop-blur-xl border border-gray-200'} shadow-xl`}>
              <div className="w-32 h-32 mx-auto mb-6 rounded-3xl bg-gradient-to-br from-primary-100 to-secondary-100 dark:from-gray-700 dark:to-gray-800 flex items-center justify-center">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-16 w-16 text-primary-600 dark:text-primary-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9.172 16.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
              </div>
              <h3 className={`text-2xl font-bold mb-3 ${isDarkMode ? 'text-white' : 'text-gray-800'}`}>
                No Products Found
              </h3>
              <p className={`text-lg ${isDarkMode ? 'text-gray-400' : 'text-gray-600'} mb-6`}>
                Try adjusting your search or browse different categories
              </p>
              <button
                onClick={() => handleCategoryChange('')}
                className="px-6 py-3 bg-gradient-to-r from-primary-500 to-secondary-500 text-white rounded-xl font-medium hover:shadow-lg hover:shadow-primary-500/30 transform hover:scale-[1.02] transition-all duration-200"
              >
                Browse All Products
              </button>
            </div>
          )}
          </div>
        </div>
      </div>

      {/* Toast Container */}
      {toasts.map(toast => (
        <Toast
          key={toast.id}
          message={toast.message}
          type={toast.type}
          duration={toast.duration}
          onClose={() => removeToast(toast.id)}
        />
      ))}
    </div>
  );
};

export default Products;
